const finite=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;
export const lightmapSuffix='.hblightmap.json';
export const createLightmapAsset=name=>({version:1,name,mode:'indirect',maps:[],bindings:[]});
export function lightmapHalf(value){if(!Number.isFinite(value)||value<0)throw Error('유한한 양수 색이 필요해요.');value=Math.min(65504,value);if(value===0)return 0;const round=v=>{const n=Math.floor(v),f=v-n;return n+Number(f>.5||f===.5&&n%2===1);};if(value<2**-14)return round(value*2**24);let exponent=Math.floor(Math.log2(value)),fraction=round((value/2**exponent-1)*1024);if(fraction===1024){exponent++;fraction=0;}return((exponent+15)<<10)|fraction;}
export const lightmapFloat=half=>(half&0x7c00)?(1+(half&1023)/1024)*2**(((half>>>10)&31)-15):(half&1023)*2**-24;
export function mergeLightmapAssets(previous,next,objects){if(!validLightmapAsset(next)||previous&&!validLightmapAsset(previous)||!Array.isArray(objects)||objects.some(id=>typeof id!=='string'||!id))throw Error('라이트맵 병합 기준을 확인하세요.');if(!previous)return structuredClone(next);const kept=previous.bindings.filter(b=>!objects.some(id=>b.key.startsWith(id+'|'))),used=[...new Set(kept.map(b=>b.page))],remap=new Map(used.map((page,i)=>[page,i])),maps=[...used.map(i=>previous.maps[i]),...next.maps].map((map,i)=>({...map,key:'page_'+i})),bindings=[...kept.map(b=>({...b,page:remap.get(b.page)})),...next.bindings.map(b=>({...b,page:b.page+used.length}))],result={...next,name:previous.name,maps,bindings};if(!validLightmapAsset(result))throw Error('라이트맵 병합 결과가 유효하지 않아요.');return result;}
export function validLightmapImage(m){return typeof m?.key==='string'&&m.key.length>0&&m.key.length<=512&&Number.isInteger(m.width)&&finite(m.width,1,8192)&&Number.isInteger(m.height)&&finite(m.height,1,8192)&&m.encoding==='rgba16f-gzip'&&typeof m.pixels==='string'&&m.pixels.length>0&&m.pixels.length<=67108864&&m.pixels.length%4===0&&/^[A-Za-z0-9+/]*={0,2}$/.test(m.pixels);}
export function validLightmapAsset(d){return d?.version===1&&typeof d.name==='string'&&d.name.length>0&&d.name.length<=80&&d.mode==='indirect'&&Array.isArray(d.maps)&&d.maps.length<=4096&&new Set(d.maps.map(m=>m?.key)).size===d.maps.length&&d.maps.every(validLightmapImage)&&Array.isArray(d.bindings)&&d.bindings.length<=1000000&&new Set(d.bindings.map(b=>b?.key)).size===d.bindings.length&&d.bindings.every(b=>typeof b.key==='string'&&b.key.length>0&&b.key.length<=512&&/^[a-f0-9]{64}$/.test(b.geometrySHA256)&&Number.isInteger(b.page)&&b.page>=0&&b.page<d.maps.length&&Array.isArray(b.scaleOffset)&&b.scaleOffset.length===4&&b.scaleOffset.every(v=>finite(v,0,1))&&b.scaleOffset[0]>0&&b.scaleOffset[1]>0&&b.scaleOffset[0]+b.scaleOffset[2]<=1+1e-10&&b.scaleOffset[1]+b.scaleOffset[3]<=1+1e-10);}
const base64=bytes=>{let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(text);};
async function transform(bytes,mode,expected){const stream=new Blob([bytes]).stream().pipeThrough(mode==='encode'?new CompressionStream('gzip'):new DecompressionStream('gzip')),reader=stream.getReader(),chunks=[];let size=0;try{while(true){const{done,value}=await reader.read();if(done)break;size+=value.length;if(expected!==undefined&&size>expected)throw Error('라이트맵 압축 해제 크기를 넘었어요.');chunks.push(value);}if(expected!==undefined&&size!==expected)throw Error('라이트맵 데이터 크기가 일치하지 않아요.');const result=new Uint8Array(size);let at=0;for(const chunk of chunks){result.set(chunk,at);at+=chunk.length;}return result;}catch(e){await reader.cancel().catch(()=>{});throw e;}finally{reader.releaseLock();}}
export async function encodeLightmapPixels(pixels){if(!(pixels instanceof Uint16Array))throw Error('Half float 픽셀이 필요해요.');const bytes=new Uint8Array(pixels.length*2),view=new DataView(bytes.buffer);for(let i=0;i<pixels.length;i++){const value=pixels[i];if((value&0x7c00)===0x7c00||value&0x8000)throw Error('유한한 양수 Half float가 필요해요.');view.setUint16(i*2,value,true);}return base64(await transform(bytes,'encode'));}
export async function decodeLightmapPixels(map){if(!validLightmapImage(map))throw Error('라이트맵 형식을 확인하세요.');const bytes=Uint8Array.from(atob(map.pixels),c=>c.charCodeAt(0)),decoded=await transform(bytes,'decode',map.width*map.height*8),view=new DataView(decoded.buffer,decoded.byteOffset,decoded.byteLength),result=new Uint16Array(map.width*map.height*4);for(let i=0;i<result.length;i++){const value=view.getUint16(i*2,true);if((value&0x7c00)===0x7c00||value&0x8000)throw Error('라이트맵 색이 유한한 양수가 아니에요.');result[i]=value;}return result;}
